<?php
$page_title='ร้านค้าในระบบ';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$where=" WHERE sp.status='approved'";$params=[];if(in_array($status,['active','suspended','closed'],true)){$where.=' AND sp.store_status=?';$params[]=$status;}if($q!==''){$where.=' AND (sp.shop_name LIKE ? OR u.username LIKE ? OR u.email LIKE ?)';$params=array_merge($params,array_fill(0,3,'%'.$q.'%'));}$sql="SELECT sp.*,u.username,u.email,c.name category_name,COUNT(DISTINCT p.id) products,COUNT(DISTINCT o.id) orders,COALESCE(SUM(oi.subtotal),0) sales FROM seller_profiles sp JOIN users u ON u.id=sp.user_id JOIN categories c ON c.id=sp.primary_category_id LEFT JOIN products p ON p.seller_id=sp.user_id LEFT JOIN order_items oi ON oi.product_id=p.id LEFT JOIN orders o ON o.id=oi.order_id AND o.order_status<>'cancelled' $where GROUP BY sp.user_id,u.username,u.email,c.name ORDER BY FIELD(sp.store_status,'suspended','active','closed'),sp.updated_at DESC";$stmt=$db->prepare($sql);$stmt->execute($params);$stores=$stmt->fetchAll();$summary=$db->query("SELECT COUNT(*) total,SUM(store_status='active') active,SUM(store_status='suspended') suspended,SUM(store_status='closed') closed FROM seller_profiles WHERE status='approved'")->fetch();require_once __DIR__.'/../includes/admin_header.php';?>
<header class="admin-page-header"><div><p class="eyebrow">MARKETPLACE</p><h1>ร้านค้าในระบบ</h1><p>ตรวจร้าน สินค้า ออเดอร์ การเงิน และความปลอดภัยจากจุดเดียว</p></div></header><div class="admin-stats-grid"><article><small>ทั้งหมด</small><strong><?php echo (int)$summary['total'];?></strong></article><article><small>เปิดขาย</small><strong><?php echo (int)$summary['active'];?></strong></article><article><small>ระงับ</small><strong><?php echo (int)$summary['suspended'];?></strong></article><article><small>ปิดร้าน</small><strong><?php echo (int)$summary['closed'];?></strong></article></div><section class="admin-panel"><form method="get" class="admin-filter-form"><input name="q" value="<?php echo e($q);?>" placeholder="ชื่อร้าน ผู้ขาย หรืออีเมล"><select name="status"><option value="">ทุกสถานะ</option><?php foreach(['active'=>'เปิดขาย','suspended'=>'ระงับ','closed'=>'ปิดร้าน'] as $key=>$label):?><option value="<?php echo $key;?>" <?php echo $status===$key?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select><button class="btn btn-primary">ค้นหา</button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ร้าน/เจ้าของ</th><th>หมวด</th><th>สินค้า</th><th>ออเดอร์</th><th>ยอดขาย</th><th>สถานะ</th><th></th></tr></thead><tbody><?php if(!$stores):?><tr><td colspan="7" class="admin-empty">ไม่พบร้านค้า</td></tr><?php endif;foreach($stores as $store):?><tr><td><strong><?php echo e($store['shop_name']);?></strong><small><?php echo e($store['username'].' · '.$store['email']);?></small></td><td><?php echo e($store['category_name']);?></td><td><?php echo (int)$store['products'];?></td><td><?php echo (int)$store['orders'];?></td><td><?php echo formatCurrency($store['sales']);?></td><td><span class="status-badge <?php echo $store['store_status']==='active'?'paid':'cancelled';?>"><?php echo e($store['store_status']);?></span></td><td><a class="btn btn-primary" href="<?php echo BASE_URL;?>admin/store-detail.php?id=<?php echo (int)$store['user_id'];?>">ตรวจร้าน</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../includes/admin_footer.php';?>
